use Illuminate\Support\Facades\Schema;
use Illuminate\Support\Facades\DB;
Schema::create('import_results', function ($t) {
    $t->id();
    $t->integer('source_item')->unique();
});
$process = function (int $stopAfter) {
    foreach (range(1, 5) as $item) {
        DB::transaction(function () use ($item) {
            DB::table('import_results')->updateOrInsert(['source_item' => $item], []);
        });
        if ($item === $stopAfter) {
            break;
        }
    }
};
$process(3);
echo DB::table('import_results')->count().':';
$process(5);
echo DB::table('import_results')->count().':'.DB::table('import_results')->distinct()->count('source_item');
